package fr.walliang.astronomy.acquisitiondelay.dao;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

/**
 * Reader of a CSV file generated by Tangra software.
 * 
 * Create a representation in memory of the file.
 */
public class TangraCsvFileReader implements FileReader {

	private static final Logger LOGGER = LogManager.getLogger(TangraCsvFileReader.class);

	private final String filename;
	
	/**
	 * TangraCsvFileReader constructor.
	 * 
	 * @param filename The path to the file to read.
	 */
	public TangraCsvFileReader(String filename) {
		this.filename = filename;
	}

	@Override
	public List<ObjectInfomation> parseFile() {
		List<ObjectInfomation> objects = new ArrayList<>();
		
		// read CSV file (made with Tangra software) and put data in memory
		Path file = Paths.get(filename);

		LOGGER.info("Reading {}", file.toAbsolutePath().toString());

		int lineNumber = 0;

		try {
			List<String> lines = Files.readAllLines(file);

			int numObjectForY = 0;
			for (String line : lines) {
				lineNumber++;
				// debug
				LOGGER.debug("Line {} : {}", lineNumber, line);

				String[] fields = line.split(",");
				// debug
				if(LOGGER.isDebugEnabled()) {
					LOGGER.debug("{}", Arrays.asList(fields));
				}


				if (fields.length < 4) {
					LOGGER.error("Line {} cannot be parsed as comma separated values. There must be at least 4 comma separated fields. Skipping this line.", lineNumber);
					continue;
				}

				try {
					int frameNumber = Integer.parseInt(fields[0]);
				} catch (NumberFormatException e) {
					LOGGER.error("Line {} column 1 is not an integer. Skipping this line.", lineNumber);
					continue;
				}
				
				// parse file to get Y coordinate of the object
				if(fields.length == 12 || fields.length == 13) {
					int y;
					
					if(fields.length == 12) {
						y = Integer.parseInt(fields[9]);
					} else {
						y = Integer.parseInt(fields[10]);
					}
					
					objects.add(new ObjectInfomation(y));
					numObjectForY++;
				}

				String time = fields[1];
				String[] timeSplit = time.split("\\.");
				if (timeSplit.length != 2) {
					LOGGER.error("Line {} column 2 cannot separate time in s and time in ms by a point. Skipping this line.", lineNumber);
					continue;
				}
				int timeInMs;
				try {
					timeInMs = Integer.valueOf(timeSplit[1].substring(0, 3));
				} catch (NumberFormatException e1) {
					LOGGER.error("Line {} column 2 cannot convert time in ms after the point to integer. Skipping this line.", lineNumber);
					continue;
				} catch (IndexOutOfBoundsException e2) {
					LOGGER.error("Line {} column 2 string after point is longer that 4 caracters. Skipping this line.", lineNumber);
					continue;
				}

				boolean skipLine = false;
				int numObject = 0;
				
				for (int col = 2; col < fields.length; col=col+2) {
					int signal;
					try {
						signal = convertDecimalStringToInt(fields[col]);
					} catch (NumberFormatException e) {
						LOGGER.error("Line {} column {} is not a decimal. Skipping this line.", lineNumber, col+1);
						skipLine = true;
						break;
					}

					int background;
					try {
						background = convertDecimalStringToInt(fields[col+1]);
					} catch (NumberFormatException e) {
						LOGGER.error("Line {} column {} is not a decimal. Skipping this line.", lineNumber, col+2);
						skipLine = true;
						break;
					}

					// reliability (case when y position is not found)
					if(objects.size() <= numObject) {
						objects.add(new ObjectInfomation(0));
					}
					ObjectInfomation object = objects.get(numObject);
					object.addMeasure(new MeasurePoint(timeInMs, signal, background));
					numObject++;
				}
				
				if(skipLine) {
					continue;
				}

			}
			LOGGER.info("Reading finished");
		} catch (IOException e) {
			LOGGER.error("Error reading file: {}", e);
		}

		return objects;
	}
	
	private static int convertDecimalStringToInt(String decimalString) throws NumberFormatException {
		double doubleValue;
		doubleValue = Double.parseDouble(decimalString);
		return (int) doubleValue;
	}
	
}
